  "/learning-track/post-rnf/assignments": {
    "title": "Post-RNF assignments",
    "description": "9 deliverables that turn the first 60 days of your real business into a compounding practice.",
    "card": "learning-track-post-rnf-assignments"
  },
  "/learning-track/post-rnf/assignments/assignment-01": {
    "title": "90-second intent statement: 3 live deliveries",
    "description": "Deliver your intent statement to 3 real prospects (live or phone) and submit the log + 1 Loom reflection.",
    "card": "learning-track-post-rnf-assignments-assignment-01"
  },
  "/learning-track/post-rnf/assignments/assignment-02": {
    "title": "Content and DM output pack: 3 posts + 5 DM conversations",
    "description": "Ship 3 feed posts answering different silent questions + open 5 real DM conversations with real exchanges.",
    "card": "learning-track-post-rnf-assignments-assignment-02"
  },
  "/learning-track/post-rnf/assignments/assignment-03": {
    "title": "Market Survey and referral ask log: 30 outreaches, 10 FACT asks",
    "description": "Run 30 warm-market outreaches (Week 4) + 10 structured referral asks (Week 5) and log every one.",
    "card": "learning-track-post-rnf-assignments-assignment-03"
  },
  "/learning-track/post-rnf/assignments/assignment-04": {
    "title": "DISC roleplay tape: 4 profiles, same scenario",
    "description": "Record 4 fact-find openings, one per DISC profile (D, I, S, C), on the same scenario. The tape shows you the gap.",
    "card": "learning-track-post-rnf-assignments-assignment-04"
  },
  "/learning-track/post-rnf/assignments/assignment-05": {
    "title": "Live pitch: full integration and 8-dimension self-review",
    "description": "One continuous recorded pitch (live to prospect or simulation, 8-15 min), scored across 8 dimensions from Weeks 1-8.",
    "card": "learning-track-post-rnf-assignments-assignment-05"
  },
  "/learning-track/post-rnf/assignments/assignment-06": {
    "title": "12-month plan: signed and delivered",
    "description": "A one-page signed Year-1 plan: FYC target, quarterly milestones, weekly rhythm, systems committed, one-thing focus.",
    "card": "learning-track-post-rnf-assignments-assignment-06"
  },
  "/learning-track/post-rnf/assignments/assignment-07": {
    "title": "Real appointment recordings: listen-along library",
    "description": "Listen to 3 real appointments run by your peers this week, including at least one on a topic you're weak on. Submit 1 takeaway per recording.",
    "card": "learning-track-post-rnf-assignments-assignment-07"
  },
  "/learning-track/post-rnf/assignments/assignment-08": {
    "title": "Audience and differentiation worksheet",
    "description": "Pick two audiences and map their tangible problems, intangible problems, and what makes YOUR approach different.",
    "card": "learning-track-post-rnf-assignments-assignment-08"
  },
  "/learning-track/post-rnf/assignments/assignment-09": {
    "title": "Lead-Gen Setup - Your Pre-Launch Checklist",
    "description": "Set up your dialling infrastructure once - business line, leads, prospecting docs, and daily tracking - before you start cold lead-gen.",
    "card": "learning-track-post-rnf-assignments-assignment-09"
  },
